import { useDrag } from '@use-gesture/react';
import { isNil, isUndefined } from 'lodash-es';
import React, { useEffect, useRef, useState } from 'react';

import type { Orientation } from '../../../../../core/types/orientation.js';
import { sanitizeLegendRatio } from '../../../functions/sanitize-legend-ratio.js';
import { Dimensions } from '../../../types/dimensions.js';
import { DEFAULT_RESIZER_WRAPPER_SIZE } from '../chart-layout.styles.js';
import { DEFAULT_LEGEND_CONFIG } from '../constants.js';
import { isVertical } from '../functions/orientation.js';
import { ChartLayoutLegendProps, ChartLayoutLegendSizes } from '../types.js';

export const calculateLegendSize = (
  orientation: Orientation,
  containerWidth: number,
  containerHeight: number,
  ratio = 25,
) => {
  const sanitizedRatio = sanitizeLegendRatio(ratio);

  const fraction = sanitizedRatio * 0.01;
  const width = isVertical(orientation)
    ? containerWidth
    : fraction * containerWidth;
  const height = !isVertical(orientation)
    ? containerHeight
    : fraction * containerHeight;

  return { width, height };
};

export const calculateGraphSize = (
  containerSize: number,
  legendSize: number,
  resizerWrapperSize: number,
) => containerSize - resizerWrapperSize - legendSize;

export interface UseResizableLayoutResponse {
  legendResizeLineRef: React.MutableRefObject<HTMLDivElement | null>;
  legendContainerRef: React.MutableRefObject<HTMLDivElement | null>;
  legendResizeContainerRef: React.MutableRefObject<HTMLDivElement | null>;
  legendWidth: number;
  legendHeight: number;
  graphSize: Dimensions;
}
const initialDimensions = {
  width: 0,
  height: 0,
};
/*
 * Method to calculate the size of the referenced element whilst dragging the
 * referenced line resizer.
 *
 */
export const useResizableLayout = (
  containerWidth: number,
  containerHeight: number,
  orientation: Orientation,
  legendConfig?: ChartLayoutLegendProps,
): UseResizableLayoutResponse => {
  const legendResizeContainerRef = useRef<HTMLDivElement | null>(null);
  const legendResizeLineRef = useRef<HTMLDivElement | null>(null);
  const legendContainerRef = useRef<HTMLDivElement | null>(null);
  const { ratio, overrideRatio } = legendConfig ?? DEFAULT_LEGEND_CONFIG;
  const { minWidth, maxHeight, maxWidth, minHeight } =
    legendConfig?.sizes ??
    (DEFAULT_LEGEND_CONFIG.sizes as ChartLayoutLegendSizes);

  const [areasSizes, setAreasSizes] = useState<{
    legend: Dimensions;
    graph: Dimensions;
  }>({
    legend: initialDimensions,
    graph: initialDimensions,
  });
  const resizerWrapperSize =
    orientation === 'horizontal'
      ? legendResizeContainerRef.current?.clientWidth ??
        DEFAULT_RESIZER_WRAPPER_SIZE
      : legendResizeContainerRef.current?.clientHeight ??
        DEFAULT_RESIZER_WRAPPER_SIZE;
  const width =
    orientation === 'horizontal'
      ? containerWidth - resizerWrapperSize
      : containerWidth;
  const height =
    orientation === 'horizontal'
      ? containerHeight
      : containerHeight - resizerWrapperSize;

  const calculateLegendRatio = isUndefined(overrideRatio)
    ? calculateLegendSize(orientation, containerWidth, containerHeight, ratio)
    : overrideRatio(orientation, width, height);

  const { width: initialWidth, height: initialHeight } = calculateLegendRatio;

  const setAreasWidthSize = (
    draggedAmount = 0,
    legendContainer: HTMLDivElement,
  ) => {
    const minLegendWidth = containerWidth * minWidth;

    if (legendContainer.clientWidth - draggedAmount <= minLegendWidth) {
      const legend: Dimensions = {
        height: containerHeight,
        width: minLegendWidth,
      };

      const graph: Dimensions = {
        width: calculateGraphSize(
          containerWidth,
          minLegendWidth,
          resizerWrapperSize,
        ),
        height: containerHeight,
      };

      return setAreasSizes({ legend, graph });
    }

    const maxWidthAllowed = (containerWidth - resizerWrapperSize) * maxWidth;
    if (legendContainer.clientWidth - draggedAmount >= maxWidthAllowed) {
      const legend: Dimensions = {
        height: containerHeight,
        width: maxWidthAllowed,
      };

      const graph: Dimensions = {
        width: calculateGraphSize(
          containerWidth,
          maxWidthAllowed,
          resizerWrapperSize,
        ),
        height: containerHeight,
      };

      return setAreasSizes({ legend, graph });
    }

    setAreasSizes(({ legend, graph }) => {
      const newLegendWidth = legend.width - draggedAmount;

      return {
        legend: {
          height: legend.height,
          width: newLegendWidth,
        },
        graph: {
          width: calculateGraphSize(
            containerWidth,
            newLegendWidth,
            resizerWrapperSize,
          ),
          height: graph.height,
        },
      };
    });
  };

  const setAreasHeightSize = (
    draggedAmount = 0,
    legendContainer: HTMLDivElement,
  ) => {
    const minLegendHeight = containerHeight * minHeight;

    if (legendContainer.clientHeight - draggedAmount <= minLegendHeight) {
      const legend: Dimensions = {
        height: minLegendHeight,
        width: containerWidth,
      };

      const graph: Dimensions = {
        width: containerWidth,
        height: calculateGraphSize(
          containerHeight,
          minLegendHeight,
          resizerWrapperSize,
        ),
      };

      return setAreasSizes({ legend, graph });
    }

    const maxHeightAllowed = (containerHeight - resizerWrapperSize) * maxHeight;
    if (legendContainer.clientHeight - draggedAmount >= maxHeightAllowed) {
      const legend: Dimensions = {
        height: maxHeightAllowed,
        width: containerWidth,
      };

      const graph: Dimensions = {
        width: containerWidth,
        height: calculateGraphSize(
          containerHeight,
          maxHeightAllowed,
          resizerWrapperSize,
        ),
      };

      return setAreasSizes({ legend, graph });
    }

    setAreasSizes(({ legend, graph }) => {
      const newLegendHeight = legend.height - draggedAmount;

      return {
        legend: {
          height: newLegendHeight,
          width: legend.width,
        },
        graph: {
          width: graph.width,
          height: calculateGraphSize(
            containerHeight,
            newLegendHeight,
            resizerWrapperSize,
          ),
        },
      };
    });
  };

  useEffect(() => {
    if (!isVertical(orientation) && initialWidth && containerWidth) {
      const maxAllowedLegendWidth = containerWidth * maxWidth;
      const legendWidth =
        initialWidth > maxAllowedLegendWidth
          ? maxAllowedLegendWidth
          : initialWidth;
      const legend = {
        height: containerHeight,
        width: legendWidth,
      };

      const graph = {
        width: calculateGraphSize(
          containerWidth,
          legendWidth,
          resizerWrapperSize,
        ),
        height: containerHeight,
      };

      setAreasSizes({ legend, graph });
    }

    if (isVertical(orientation) && initialHeight && containerHeight) {
      const maxAllowedLegendHeight = containerHeight * maxHeight;
      const legendHeight =
        initialHeight > maxAllowedLegendHeight
          ? maxAllowedLegendHeight
          : initialHeight;
      const legend = {
        height: legendHeight,
        width: containerWidth,
      };

      const graph = {
        width: containerWidth,
        height: calculateGraphSize(
          containerHeight,
          legendHeight,
          resizerWrapperSize,
        ),
      };

      setAreasSizes({
        legend,
        graph,
      });
    }
  }, [
    containerWidth,
    initialWidth,
    orientation,
    initialHeight,
    containerHeight,
    resizerWrapperSize,
  ]);

  useDrag(
    (dragEvent) => {
      const [horizontalDraggedAmount, verticalDraggedAmount] =
        dragEvent['delta'];

      const currentLegendContainer = legendContainerRef.current;
      if (isNil(currentLegendContainer)) {
        return;
      }

      isVertical(orientation)
        ? setAreasHeightSize(verticalDraggedAmount, currentLegendContainer)
        : setAreasWidthSize(horizontalDraggedAmount, currentLegendContainer);
    },
    {
      target: legendResizeLineRef,
      eventOptions: { passive: false },
      drag: { filterTaps: true },
    },
  );

  return {
    legendWidth: areasSizes.legend.width,
    legendHeight: areasSizes.legend.height,
    graphSize: areasSizes.graph,
    legendResizeLineRef,
    legendContainerRef,
    legendResizeContainerRef,
  };
};
